"use client";

import type { CSSProperties } from "react";
import manifest from "../../../public/cosmic/img/anim/manifest.json";

/**
 * A generated scene as an animated stage: sky, a rotating planet, an optional
 * ring, three groups of twinkling stars and an optional shooting star. It is
 * the `.fx` stage chrome.js builds in the mockups, driven by the same table
 * (`public/cosmic/img/anim/manifest.json`, generated by `anim_manifest.py`).
 *
 * Put it first inside a `.hero` or `.pagehead` that already paints the scene's
 * still image as its background (`--head` / the hero image): the section keeps
 * that still as the fallback, and cosmic.css animates the layers ("scene
 * motion"). Reduced motion is handled there too: the planet holds frame 0 and
 * the shooting star stays hidden, while the twinkle keeps running.
 */

type Box = readonly [number, number, number, number];
type Planet = readonly [string, number, number, ...Box];
type Ring = readonly [string, ...Box];
type Shoot = readonly [string, ...Box];

interface SceneSpec {
  ar: string;
  sky: string;
  planet: Planet;
  ring?: Ring;
  tw: string;
  shoot?: Shoot;
}

const SCENES = manifest as unknown as Record<string, SceneSpec>;

export type SceneName = keyof typeof manifest;

const DIR = "/cosmic/img/anim";
const url = (file: string) => ({ backgroundImage: `url(${DIR}/${file})` });
const box = ([l, t, w, h]: Box) =>
  ({
    "--l": `${l}%`,
    "--t": `${t}%`,
    "--w": `${w}%`,
    "--h": `${h}%`,
  }) as CSSProperties;

export default function Scene({ name }: { name: SceneName }) {
  const scene = SCENES[name];
  if (!scene) return null;
  const [planetFile, frames, seconds, ...planetBox] = scene.planet;

  return (
    <div
      className="fx"
      aria-hidden="true"
      style={{ "--ar": scene.ar } as CSSProperties}
    >
      <div className="stage">
        <i className="sky" style={url(scene.sky)} />
        <i
          className="planet"
          style={
            {
              ...url(planetFile),
              ...box(planetBox),
              "--n": frames,
              "--spin": `${seconds}s`,
            } as CSSProperties
          }
        />
        {scene.ring && (
          <i
            className="orbit"
            style={{
              ...url(scene.ring[0]),
              ...box(scene.ring.slice(1) as unknown as Box),
            }}
          />
        )}
        {[0, 1, 2].map((group) => (
          <i key={group} className={`tw tw${group}`} style={url(scene.tw)} />
        ))}
        {scene.shoot && (
          <i
            className="shoot"
            style={{
              ...url(scene.shoot[0]),
              ...box(scene.shoot.slice(1) as unknown as Box),
            }}
          />
        )}
      </div>
    </div>
  );
}
